mapper.select:
select * from pm_agent_call
where project_id = #{projectId} and initiator_id = #{initiatorId}
  and idempotency_key = #{idempotencyKey}
order by call_id desc limit 1

select c.* from pm_agent_call c
inner join pm_project_member m on m.project_id = c.project_id and m.user_id = #{userId}
where c.project_id = #{projectId}
  and c.requirement_id = #{requirementId}
order by c.create_time desc, c.call_id desc
